--
-- TOC entry 620 (class 1255 OID 41444)
-- Name: fn_acorn_sumproduct(double precision[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_acorn_sumproduct(VARIADIC ints double precision[]) RETURNS double precision
    LANGUAGE plpgsql
    AS $$
declare
	len int;
	result double precision;
	values double precision[];
	weights double precision[];
begin
	len     := array_upper(ints,1) / 2;
	values  := ints[1:len];
	weights := ints[len+1:];

	result := 0;
	for i in 1..len loop
		result := result + (values[i] * weights[i]);
	end loop;

	return result;
end
$$;


