-- TOC entry 583 (class 1255 OID 41447)
-- Name: fn_acorn_truncate_database(character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_acorn_truncate_database(schema_like character varying, table_like character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
            declare
reset_query varchar(32596);
            begin
        reset_query = (SELECT 'TRUNCATE TABLE '
              || string_agg(format('%I.%I', schemaname, tablename), ', ')
              || ' CASCADE'
            FROM   pg_tables
            WHERE  schemaname like(schema_like)
            AND tablename like(table_like)
          );
        if not reset_query is null then
          execute reset_query;
        end if;
end;
            $$;


--
-- TOC entry 585 (class 1255 OID 41448)
-- Name: fn_acorn_university_academic_year_semesters_prov_cys(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_acorn_university_academic_year_semesters_prov_cys() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
	p_course_name character varying(1024);
	p_course_type_id uuid;
begin
	-- AFTER INSERT of new AYS
	-- Course Plans for this year will not have this AYS because it did not exist
	-- Provision a CYS for every Course Plan in that year
	-- tr/fn_acorn_university_cys_manage_hierarchy()
	--   will add the CYS into the hierarchy
	-- tr/fn_acorn_university_hierarchies_new_version()
	--   will add a new user group version
	-- tr/fn_acorn_university_enrollment_year
	--   will complete enrollment_academic_year_id
	-- tr/fn_acorn_university_semester_ordinal_insert
	--   will complete academic_year_semester_ordinal
	-- TODO: Default semester group aware

	/* 
	// TODO: insert into acorn_university_course_year_semesters for each course plan
	insert into acorn_university_course_year_semesters(
		course_id, course_year_id, academic_year_semester_id, entity_id, 
		course_plan_id, course_specialization_id
	)
		select 
		where
		
		and ays.academic_year_id = new.academic_year_id;
	*/
	return new;
end;
$$;


--
-- TOC entry 649 (class 1255 OID 41449)
-- Name: fn_acorn_university_academic_years_copy_to(uuid, uuid, uuid, boolean, boolean, boolean, boolean, boolean, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_acorn_university_academic_years_copy_to(p_old_academic_year_id uuid, p_new_academic_year_id uuid, p_user_id uuid, p_copy_hierarchy boolean DEFAULT false, p_copy_semesters boolean DEFAULT false, p_copy_materials boolean DEFAULT false, p_copy_seminars boolean DEFAULT false, p_copy_calculations boolean DEFAULT false, p_old_parent_id uuid DEFAULT NULL::uuid, p_new_parent_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
declare
	p_description text;
	p_year_diff interval;
	-- p_new_hids uuid[];
	p_uuids uuid[];
begin
	select 'Copied from ' || name into p_description 
		from acorn_university_academic_years 
		where id = p_old_academic_year_id;

	-- ------------------------------------------------ Copy Semesters
	if p_copy_semesters then
		-- Year Diff between new and old to add to the dates of the semesters
		select ('P' || extract(year from ep_new.start) - extract(year from ep_old.start) || 'Y')::interval into p_year_diff
			from acorn_university_academic_years ay_old
			inner join acorn_calendar_events ev_old on ev_old.id = ay_old.event_id
			inner join acorn_calendar_event_parts ep_old on ep_old.event_id = ev_old.id,
			
			acorn_university_academic_years ay_new
			inner join acorn_calendar_events ev_new on ev_new.id = ay_new.event_id
			inner join acorn_calendar_event_parts ep_new on ep_new.event_id = ev_new.id

			where ay_old.id = p_old_academic_year_id
			and ay_new.id = p_new_academic_year_id;	
		-- raise exception 'Diff: %', p_year_diff;
		
		with inserted as (
			insert into acorn_university_academic_year_semesters(academic_year_id, semester_id, created_by_user_id, event_id)
				select p_new_academic_year_id, ays_old.semester_id, p_user_id,
				fn_acorn_calendar_create_event(
					ev_old.calendar_id, p_user_id, ep_old.type_id, ep_old.status_id, 
					'Semester ' || ay_new.name || '::' || sem_old.name,
					ep_old.start + p_year_diff, 
					ep_old.end   + p_year_diff
				)
				-- From Academic Year
				from acorn_university_academic_years ay_old
				inner join acorn_university_academic_year_semesters ays_old on ay_old.id = ays_old.academic_year_id
				inner join acorn_university_semesters sem_old on sem_old.id = ays_old.semester_id
				inner join acorn_calendar_events ev_old on ev_old.id = ays_old.event_id
				inner join acorn_calendar_event_parts ep_old on ep_old.event_id = ev_old.id
				-- New Academic Year (semesters being insterted)
				cross join acorn_university_academic_years ay_new
				
				where ay_old.id = p_old_academic_year_id
				and ay_new.id = p_new_academic_year_id
				on conflict do nothing -- Don't overwrite existing entries
				returning id
		) 
		select array_agg(inserted.id) into p_uuids from inserted;
		-- raise exception 'Inserted: %', array_upper(p_uuids, 1);
	end if;

	-- ------------------------------------------------ Copy (merge) Hierarchy
	-- Recursive, merge
	-- Note that entities can have multiple hierarchy parents
	-- thus the recursive copy
	if p_copy_hierarchy then
		with inserted as (
			insert into acorn_university_hierarchies(
				entity_id, academic_year_id, 
				parent_id, 
				created_by_user_id, description, 
				import_source
			)
				select 
					hi_old.entity_id, p_new_academic_year_id, 
					p_new_parent_id, -- NULL at top level
					p_user_id, hi_old.description, 
					-- Temp id cache
					-- We add p_new_academic_year_id so it will not temporarily fail on unique import_source
					p_new_academic_year_id::character varying(36) || ' ' || hi_old.id::character varying(36) 
				from acorn_university_hierarchies hi_old
				where hi_old.academic_year_id = p_old_academic_year_id
				and (hi_old.parent_id = p_old_parent_id or (p_old_parent_id is NULL and hi_old.parent_id is NULL))
				returning import_source as old_id, id as new_id
			) -- => Recursion:
				select array_agg(fn_acorn_university_academic_years_copy_to(
						p_old_academic_year_id, p_new_academic_year_id, p_user_id,
						p_copy_hierarchy, p_copy_semesters, p_copy_materials, p_copy_seminars, p_copy_calculations,
						substr(inserted.old_id, 38)::uuid, inserted.new_id
					)) into p_uuids
				from inserted;
	
		-- TODO: Get inserted in to p_new_hids, and update things...
		-- update acorn_university_hierarchies set import_source = p_description || ':' || import_source
		-- 	where id in(select unnest from unnest(p_new_hids));
	end if;

	if p_copy_materials then
		raise exception 'Copy course materials is not complete';
	end if;

	if p_copy_seminars then
		raise exception 'Copy seminars is not complete';
	end if;
	
	-- ------------------------------------------------ Copy (merge) Calculations
	if p_copy_calculations then
		with inserted as (
			insert into acorn_exam_calculations(
				name, description, expression, 
				created_by_user_id, updated_by_user_id, server_id, 
				minimum, maximum, required, calculation_type_id, parent_id, owner_entity_id, 
				nest_left, nest_right, nest_depth, 
				academic_year_id, code
			)
				select name, description, expression, 
					created_by_user_id, updated_by_user_id, server_id, 
					minimum, maximum, required, calculation_type_id, parent_id, owner_entity_id, 
					nest_left, nest_right, nest_depth, 
					p_new_academic_year_id, 
					-- Temporary id cache
					code || id
				from acorn_exam_calculations
				where academic_year_id = p_old_academic_year_id
			on conflict do nothing
			returning id
		) select array_agg(inserted.id) into p_uuids from inserted;
		
		-- The parent_ids are still pointing to the old previous year nodes
		-- Use the temp cache: the new nodes have the old ids in the code field
		update acorn_exam_calculations ec
			set parent_id = (
				select id 
				from acorn_exam_calculations 
				where substr(code, length(code)-35)::uuid = ec.parent_id
				and not array_position(p_uuids, id) is null
			)
			where not array_position(p_uuids, ec.id) is null;

		-- Copy the calculation links where possible
		-- There are 4 categories
		insert into acorn_exam_calculation_course(calculation_id, course_id)
			select calc_new.id, cc_old.course_id
			from 
			-- Newly created calcs
			acorn_exam_calculations calc_new
			-- Join to the previous calcs courses
			inner join acorn_exam_calculation_course cc_old
				on substr(calc_new.code, length(calc_new.code)-35)::uuid = cc_old.calculation_id
			where not array_position(p_uuids, calc_new.id) is null
			on conflict do nothing;
		insert into acorn_exam_calculation_course_material(calculation_id, course_material_id)
			select calc_new.id, cc_old.course_material_id
			from 
			-- Newly created calcs
			acorn_exam_calculations calc_new
			-- Join to the previous calcs courses
			inner join acorn_exam_calculation_course_material cc_old
				on substr(calc_new.code, length(calc_new.code)-35)::uuid = cc_old.calculation_id
			where not array_position(p_uuids, calc_new.id) is null
			on conflict do nothing;
		insert into acorn_exam_calculation_course_type(calculation_id, course_type_id)
			select calc_new.id, cc_old.course_type_id
			from 
			-- Newly created calcs
			acorn_exam_calculations calc_new
			-- Join to the previous calcs courses
			inner join acorn_exam_calculation_course_type cc_old
				on substr(calc_new.code, length(calc_new.code)-35)::uuid = cc_old.calculation_id
			where not array_position(p_uuids, calc_new.id) is null
			on conflict do nothing;
		insert into acorn_exam_calculation_material_type(calculation_id, material_type_id)
			select calc_new.id, cc_old.material_type_id
			from 
			-- Newly created calcs
			acorn_exam_calculations calc_new
			-- Join to the previous calcs courses
			inner join acorn_exam_calculation_material_type cc_old
				on substr(calc_new.code, length(calc_new.code)-35)::uuid = cc_old.calculation_id
			where not array_position(p_uuids, calc_new.id) is null
			on conflict do nothing;
			
		-- Remove temporary id cache
		update acorn_exam_calculations ec
			set code = substr(code, 1, length(code)-36)
			where not array_position(p_uuids, ec.id) is null;
	end if;
		
	return p_new_academic_year_id;
end;
$$;


--
-- TOC entry 810 (class 1255 OID 41451)
-- Name: fn_acorn_university_academic_years_current(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_acorn_university_academic_years_current() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
	-- Enforce only one current
	if new.current then
		-- Unset the old current(s)
		update acorn_university_academic_years
			set "current" = false
			where "current" and id != new.id; 
	end if;
	return new;
end;
$$;


--
-- TOC entry 594 (class 1255 OID 41452)
-- Name: fn_acorn_university_action_academic_years_clear(uuid, uuid, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_acorn_university_action_academic_years_clear(model_id uuid, user_id uuid, p_clear_course_materials boolean DEFAULT false, p_for_enrollment_year boolean DEFAULT false, p_clear_exams_and_scores boolean DEFAULT false, p_confirm boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
	if p_confirm then
		delete from acorn_university_hierarchies where academic_year_id = model_id;

		if p_clear_course_materials or p_clear_exams_and_scores then
			-- This will casscade to scores
			if p_for_enrollment_year then
				-- For the enrollment year
				delete from acorn_exam_exam_materials
					where course_material_id in(
						select cm.id from acorn_university_course_materials cm
						inner join acorn_university_course_year_semesters cys on cm.course_year_semester_id = cys.id
						where cys.enrollment_academic_year_id = model_id
					);
			else
				-- For the year
				delete from acorn_exam_exam_materials
					where course_material_id in(
						select cm.id from acorn_university_course_materials cm
						inner join acorn_university_course_year_semesters cys on cm.course_year_semester_id = cys.id
						inner join acorn_university_academic_year_semesters ays on ays.id = cys.academic_year_semester_id
						where ays.academic_year_id = model_id
					);
			end if;
		end if;
		
		if p_clear_course_materials then
			-- This will cascade to calculation_course_materials
			if p_for_enrollment_year then
				-- For the enrollment year
				delete from acorn_university_course_materials
					where id in(
						select cm.id from acorn_university_course_materials cm
						inner join acorn_university_course_year_semesters cys on cm.course_year_semester_id = cys.id
						where cys.enrollment_academic_year_id = model_id
					);
			else
				-- For the year
				delete from acorn_university_course_materials
					where id in(
						select cm.id from acorn_university_course_materials cm
						inner join acorn_university_course_year_semesters cys on cm.course_year_semester_id = cys.id
						inner join acorn_university_academic_year_semesters ays on ays.id = cys.academic_year_semester_id
						where ays.academic_year_id = model_id
					);
			end if;
		end if;
	end if;
end;
$$;


