-- TOC entry 729 (class 1255 OID 41521)
-- Name: fn_acorn_updated_by_user_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_acorn_updated_by_user_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
declare
begin
	-- BEFORE UPDATE on tables with updated_by_user_id
	-- DBAuth required
	-- Will return NULL if not regexp_like(CURRENT_USER, '^token_[0-9]+$')
	if new.updated_by_user_id is null then
		select u.id into new.updated_by_user_id from public.acorn_dbauth_user u;
	end if;
    return new;
end;
            
$_$;


--
-- TOC entry 783 (class 1255 OID 41396)
-- Name: fn_acorn_user_code(character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_acorn_user_code(name character varying, word integer DEFAULT 0, length integer DEFAULT 3) RETURNS character varying
    LANGUAGE sql
    AS $$
	select substr(upper(
		case word
			when 0 then
				regexp_replace(name, '[^a-zA-Z0-9]', '')
			when 1 then
				regexp_replace(regexp_replace(name, '^[^ ]* ', ''), '[^a-zA-Z0-9]', '')
			else
				regexp_replace(regexp_replace(name, '^[^ ]* [^ ]* ', ''), '[^a-zA-Z0-9]', '')
		end), 1, length);
$$;


--
-- TOC entry 558 (class 1255 OID 41397)
-- Name: fn_acorn_user_code_acronym(character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_acorn_user_code_acronym(name character varying, word integer DEFAULT 0, length integer DEFAULT 3) RETURNS character varying
    LANGUAGE sql
    AS $$
	select 
		substr(upper(
			regexp_replace(regexp_replace(regexp_replace(name, 
			'[^a-zA-Z0-9 ]', '', 'g'),
			'([^ ])[^ ]+', '\1', 'g'),
			' +', '', 'g')
		), word+1, length);
$$;


--
-- TOC entry 748 (class 1255 OID 41522)
-- Name: fn_acorn_user_get_seed_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_acorn_user_get_seed_user() RETURNS uuid
    LANGUAGE plpgsql
    AS $$
            declare
user_id uuid;
            begin
            -- Lazy create the seeder user
            select into user_id uu.id 
                from public.acorn_user_users uu
                where name = 'seeder' and is_system_user limit 1;
            if user_id is null then
                insert into public.acorn_user_users(name, is_system_user)
                    values('seeder', true) 
                    returning id into user_id;
            end if;
            
            
            return user_id;
end;
            $$;


--
-- TOC entry 448 (class 1255 OID 42239)
-- Name: fn_acorn_user_user_group_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_acorn_user_user_group_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE acorn_user_user_group_users
       SET period     = daterange(lower(period), CURRENT_DATE),
           updated_at = NOW()
     WHERE user_id       = OLD.user_id
       AND user_group_id = OLD.user_group_id
       AND period @> CURRENT_DATE;
    RETURN NULL;
END;
$$;


--
-- TOC entry 466 (class 1255 OID 42237)
-- Name: fn_acorn_user_user_group_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_acorn_user_user_group_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO acorn_user_user_group_users
        (user_id, user_group_id, period, created_at, updated_at)
    VALUES
        (NEW.user_id, NEW.user_group_id,
         daterange(CURRENT_DATE, NULL),
         NOW(), NOW())
    ON CONFLICT DO NOTHING;
    RETURN NULL;
END;
$$;


